#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    long long m;
    cin >> n >> m;
    vector<vector<long long>> edges(m, vector<long long>(2));
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < 2; j++) {
            cin >> edges[i][j];
        }
    }

    vector<long long> outDegree(n + 1, 0), inDegree(n + 1, 0);
    for (const vector<long long>& e : edges) {
        outDegree[e[0]]++;
        inDegree[e[1]]++;
    }
    long long judge = -1;
    for (int v = 1; v <= n; v++) {
        if (outDegree[v] == 0 && inDegree[v] == n - 1) {
            judge = v;
            break;
        }
    }
    cout << judge << "\n";

    return 0;
}

